function crc32(bytes){let c=-1;for(const b of bytes){c^=b;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1}return(c^-1)>>>0}
export async function creditedPNG(blob,credits){const bytes=new Uint8Array(await blob.arrayBuffer()),text=new TextEncoder().encode('Sources\0\0\0\0\0'+JSON.stringify(credits)),type=new TextEncoder().encode('iTXt'),chunk=new Uint8Array(12+text.length),v=new DataView(chunk.buffer);v.setUint32(0,text.length);chunk.set(type,4);chunk.set(text,8);v.setUint32(8+text.length,crc32(chunk.slice(4,8+text.length)));return new Blob([bytes.slice(0,-12),chunk,bytes.slice(-12)],{type:'image/png'})}
